{"explanation":"Slice both solids into thin horizontal layers. Every layer of the cylinder is a full disc of area πr². A cone layer at height y has a radius that shrinks in a straight line, r(1 − y/h), so its area is πr²(1 − y/h)². Since the radius shrinks linearly, the area shrinks as a square. Adding up the layers gives V_cone/V_cyl = ∫₀¹(1−u)² du = 1/3. Use the "Slices" slider to see the stacked slabs get closer to exactly one third, and the "Cut height" slider to compare matching cross-sections of the two solids.","manimCode":"const R = 1.2, H = 4, BASE = -2.6, EY = 0.25;
const cylX = -5, coneX = -2;

function ellipsePts(cx, cy, rx, ry) {
  const pts = [];
  for (let i = 0; i < 48; i++) {
    const a = (2 * Math.PI * i) / 48;
    pts.push([cx + rx * Math.cos(a), cy + ry * Math.sin(a), 0]);
  }
  return pts;
}
function seg(p, q, color) {
  const s = new Polygon({ vertices: [p, q], color: color });
  s.setStrokeWidth(3); s.setFillOpacity(0);
  return s;
}
function ell(cx, cy, rx, color) {
  const e = new Polygon({ vertices: ellipsePts(cx, cy, rx, rx * EY), color: color });
  e.setStrokeWidth(3); e.setFillOpacity(0);
  return e;
}

// Outlines
const cylOutline = [
  ell(cylX, BASE, R, BLUE), ell(cylX, BASE + H, R, BLUE),
  seg([cylX - R, BASE, 0], [cylX - R, BASE + H, 0], BLUE),
  seg([cylX + R, BASE, 0], [cylX + R, BASE + H, 0], BLUE)
];
const coneOutline = [
  ell(coneX, BASE, R, ORANGE),
  seg([coneX - R, BASE, 0], [coneX, BASE + H, 0], ORANGE),
  seg([coneX + R, BASE, 0], [coneX, BASE + H, 0], ORANGE)
];

const title = new MathTex({ latex: 'V_{\\text{cone}} = \\tfrac{1}{3}\\,V_{\\text{cyl}} = \\tfrac{1}{3}\\pi r^2 h' });
await title.waitForRender();
title.scale(0.8);
title.moveTo([-3.5, 3.3, 0]);

const cylLbl = new Text({ text: 'Cylinder', color: BLUE, fontSize: 24 });
cylLbl.moveTo([cylX, -3.3, 0]);
const coneLbl = new Text({ text: 'Cone', color: ORANGE, fontSize: 24 });
coneLbl.moveTo([coneX, -3.3, 0]);

await scene.play(new AnimationGroup([...cylOutline, ...coneOutline].map(m => new Create(m))));
await scene.play(new AnimationGroup([new FadeIn(cylLbl), new FadeIn(coneLbl), new Write(title)]));

// Graph of cross-section ratio
const ax = new Axes({ xRange: [0, 1, 0.25], yRange: [0, 1, 0.25], xLength: 4.2, yLength: 3.4, tips: false });
ax.moveTo([3.1, -0.6, 0]);
const curve = ax.plot(u => (1 - u) * (1 - u), { color: ORANGE });
const area = ax.getArea(curve, [0, 1], { color: ORANGE, opacity: 0.15 });
