const uLbl = new MathTex({ latex: 'y/h' });
await uLbl.waitForRender();
uLbl.scale(0.6);
uLbl.moveTo(ax.c2p(1.08, -0.08));
await scene.play(new AnimationGroup([new Create(ax), new Create(curve), new FadeIn(area), new Write(fLbl), new FadeIn(uLbl)]));

