const cutCyl = new Polygon({ vertices: ellipsePts(cylX, BASE, R, R * EY), color: WHITE });
cutCyl.setFill(BLUE_B, 0.6); cutCyl.setStrokeWidth(2);
const cutCone = new Polygon({ vertices: ellipsePts(coneX, BASE, R, R * EY), color: WHITE });
cutCone.setFill(YELLOW, 0.7); cutCone.setStrokeWidth(2);
const cutDot = new Dot({ point: ax.c2p(0, 1), color: WHITE });
