  cutCyl.setVertices(ellipsePts(cylX, y, R, R * EY));
  cutCone.setVertices(ellipsePts(coneX, y, rc, rc * EY));
  const f = (1 - cutU) * (1 - cutU);
  cutDot.moveTo(ax.c2p(cutU, f));
  cutLine.setVertices([ax.c2p(cutU, 0), ax.c2p(cutU, f)]);
}
updateCut();
